//
// This fork changes the original by adding arbitrary rounding to the ring corners. 
//
// Distance to a section of a ring.
//
// List of some other 2D distances: https://www.shadertoy.com/playlist/MXdSRf
//
// and https://iquilezles.org/articles/distfunctions2d


float sdRoundedRing( in vec2 p, in vec2 n, in float r, in float th, in float ro )
{
    // inset the shape by the radius
    ro = min(ro, th * 0.5);
    th = max(0., th - ro*2.);
    float eoff = min(0., -ro); // Controls linear offset of the end cap. This could be separate control, which would let the user to decide if the caps will butt out.

    // Handle symmetrically.
    p.x = abs(p.x);

    p = mat2(n.x,n.y,-n.y,n.x)*p;

    float dp = length(p);

    // distance to the arc
    float dring = abs(dp-r)-th*0.5;

    float r0 = r-th*0.5;
    float r1 = r+th*0.5;

    // distance to the arc end cap
    float y0 = sqrt(max(0., r0*r0 - eoff*eoff));
    float y1 = sqrt(max(0., r1*r1 - eoff*eoff));
    vec2 pcap = vec2(p.x-eoff, max(0.0,abs((y1+y0)*0.5 - p.y) - (y1-y0)*0.5)); // nearest point on the end cap.
    float dend = length(pcap);

    vec2 edge0 = vec2(eoff,y0);
    float side0 = -dot(p, vec2(-edge0.y, edge0.x));
    vec2 edge1 = vec2(eoff,y1);
    float side1 = -dot(p, vec2(-edge1.y, edge1.x));

    // TODO: There's probably simpler way to express this!
    // p.x and p.y are used to mask out certain quadrants as they otherwise "leak" when the arc is almost fully open or closed.
    if (max(p.y, p.x) > 0.) {
        // inside the ring
        if (p.y > 0. && dp < r0 && side0 < 0.)
            return dring - ro;
        // End point
        if (side1 > 0. || sign(p.x-eoff) > 0.)
            return dend - ro;
        // Inside the ring
        if (dp < r1)
            return max(dring, -dend) - ro;
    }

    // Outside the ring
    return dring - ro;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalized pixel coordinates
    vec2 p = (2.0*fragCoord-iResolution.xy)/iResolution.y;
    vec2 m = (2.0*iMouse.xy-iResolution.xy)/iResolution.y;

    // animation
    float t = 3.14159*(0.5+0.5*cos(iTime*0.52+1.0));
    float t2 = (0.5+0.5*cos(iTime*0.72+2.1));
    vec2 cs = vec2(cos(t),sin(t));
    const float ra = 0.5;
    const float th = 0.2;
    float rad = th * t2;

    // distance
    float d = sdRoundedRing(p, cs, ra, th, rad);

    // coloring
    vec3 col = (d>0.0) ? vec3(0.9,0.6,0.3) : vec3(0.65,0.85,1.0);
	col *= 1.0 - exp2(-25.0*abs(d));
	col *= 0.8 + 0.2*cos(120.0*abs(d));
	col = mix( col, vec3(1.0), 1.0-smoothstep(0.0,0.01,abs(d)) );

    // mouse interaction
    if( iMouse.z>0.001 )
    {
        d = sdRoundedRing(m, cs, ra, th, rad);
        col = mix(col, vec3(1.0,1.0,0.0), 1.0-smoothstep(0.0, 0.005, abs(length(p-m)-abs(d))-0.0025));
        col = mix(col, vec3(1.0,1.0,0.0), 1.0-smoothstep(0.0, 0.005, length(p-m)-0.015));
    }

	fragColor = vec4(col, 1.0);
}
